head.script:
scwin.onpageload = function() {
    dtl_lbDbCompSlips.setJSON([{}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}]);
    for (var i = 1; i <= 50; i++) {
        gv_data.setHeaderStyle("data" + i + "H6", "display", "none");
        gv_data.setHeaderStyle("data" + i + "H5", "display", "none");
        gv_data.setHeaderStyle("data" + i + "H4", "display", "none");
        gv_data.setHeaderStyle("data" + i + "H3", "display", "none");
        gv_data.setHeaderStyle("data" + i + "H2", "display", "none");
    }
    gv_data.setHeaderStyle("tdata1H2", "display", "none");
    gv_data.refresh(true);
    debugger;
};
scwin.onpageunload = function() {};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gv_data_body_table').height() > 420", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
